function clean($v){return trim((string)$v);}
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??'';
  if($action==='save'){
    $vals=[]; $types=''; $params=[];
    foreach($c['fields'] as $name=>$f){ $v=isset($_POST[$name])?clean($_POST[$name]):null; $vals[$name]=($v==='')?null:$v; }
    if(!empty($_POST['id'])){
      $sets=[]; foreach($vals as $k=>$v){$sets[]="`$k`=?"; $types.='s'; $params[]=$v;} $types.='i'; $params[]=(int)$_POST['id'];
      $stmt=$conn->prepare("UPDATE `$table` SET ".implode(',',$sets)." WHERE id=?"); $stmt->bind_param($types,...$params);
    } else {
      $cols=array_keys($vals); $types=str_repeat('s',count($cols)); $params=array_values($vals); $marks=implode(',',array_fill(0,count($cols),'?'));
      $stmt=$conn->prepare("INSERT INTO `$table` (`".implode('`,`',$cols)."`) VALUES ($marks)"); $stmt->bind_param($types,...$params);
    }
    if($stmt && $stmt->execute()){$msg='Saved successfully.';} else {$err=$stmt?$stmt->error:$conn->error;}
  } elseif($action==='delete' && !empty($_POST['id'])) { $id=(int)$_POST['id']; $stmt=$conn->prepare("DELETE FROM `$table` WHERE id=?"); $stmt->bind_param('i',$id); $msg=$stmt->execute()?'Deleted successfully.':$stmt->error; }
}
